const ROBOT = {"CODE": "b24hub_inn_check", "HANDLER": "https://n8n.144-31-229-139.sslip.io/webhook/b24hub/app/robot", "USE_SUBSCRIPTION": "Y", "NAME": {"ru": "Проверить контрагента по ИНН", "en": "Check counterparty by INN"}, "DESCRIPTION": {"ru": "DaData: наименование, статус, КПП, ОГРН, адрес по ИНН (b24-lead-hub)"}, "PROPERTIES": {"INN": {"Name": {"ru": "ИНН", "en": "INN"}, "Type": "string", "Required": "Y"}}, "RETURN_PROPERTIES": {"CHECK_RESULT": {"Name": {"ru": "Результат проверки"}, "Type": "string"}, "COMPANY_NAME": {"Name": {"ru": "Наименование"}, "Type": "string"}, "STATUS": {"Name": {"ru": "Статус (ЕГРЮЛ)"}, "Type": "string"}, "IS_ACTIVE": {"Name": {"ru": "Действующая"}, "Type": "bool"}, "KPP": {"Name": {"ru": "КПП"}, "Type": "string"}, "OGRN": {"Name": {"ru": "ОГРН"}, "Type": "string"}, "ADDRESS": {"Name": {"ru": "Адрес"}, "Type": "text"}}, "DOCUMENT_TYPE": ["crm", "CCrmDocumentDeal", "DEAL"], "FILTER": {"INCLUDE": [["crm", "CCrmDocumentDeal"]]}};
function setupCmd() {
